-- CPF_LOGICAL_DATABASE=cpfDB
-- CEC Center-Cut Runner role currentization. Existing history remains immutable.
CREATE TEMPORARY TABLE cpf_v138_runtime_role_guard (invalid_count BIGINT NOT NULL, CONSTRAINT ck_cpf_v138_runtime_role_guard CHECK (invalid_count = 0));
INSERT INTO cpf_v138_runtime_role_guard(invalid_count) SELECT COUNT(*) FROM (SELECT runtime_role FROM OPS_RUNTIME_INSTANCE_STATE UNION ALL SELECT runtime_role FROM BAT_RUNTIME_INSTANCE UNION ALL SELECT runtime_role FROM BAT_DEPLOYMENT_CELL) r WHERE runtime_role IS NOT NULL AND BINARY runtime_role NOT IN ('APPLICATION','CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT','CENTER_CUT_RUNNER','AGENT');
UPDATE OPS_RUNTIME_INSTANCE_STATE SET runtime_role='CENTER_CUT_RUNNER' WHERE BINARY runtime_role='CENTER_CUT';
UPDATE BAT_RUNTIME_INSTANCE SET runtime_role='CENTER_CUT_RUNNER' WHERE BINARY runtime_role='CENTER_CUT';
UPDATE BAT_DEPLOYMENT_CELL SET runtime_role='CENTER_CUT_RUNNER' WHERE BINARY runtime_role='CENTER_CUT';
ALTER TABLE OPS_RUNTIME_INSTANCE_STATE DROP CONSTRAINT ck_ops_runtime_instance_role;
ALTER TABLE BAT_RUNTIME_INSTANCE DROP CONSTRAINT ck_bat_runtime_instance_role;
ALTER TABLE BAT_DEPLOYMENT_CELL DROP CONSTRAINT ck_bat_deployment_runtime_role;
ALTER TABLE OPS_RUNTIME_INSTANCE_STATE ADD CONSTRAINT ck_ops_runtime_instance_role CHECK (runtime_role IS NULL OR BINARY runtime_role IN ('APPLICATION','CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT_RUNNER','AGENT'));
ALTER TABLE BAT_RUNTIME_INSTANCE ADD CONSTRAINT ck_bat_runtime_instance_role CHECK (BINARY runtime_role IN ('CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT_RUNNER','AGENT'));
ALTER TABLE BAT_DEPLOYMENT_CELL ADD CONSTRAINT ck_bat_deployment_runtime_role CHECK (BINARY runtime_role IN ('CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT_RUNNER','AGENT'));
DROP TEMPORARY TABLE cpf_v138_runtime_role_guard;
